#Run the following command in the same directory file to generate the log file
#sudo sysdig "(evt.type=execve) or ((evt.type=read or evt.type=write or evt.type=writev or evt.type=readv) and (proc.name=wget or proc.name=cp))" -p"*%proc.name;%evt.type;%evt.category;%fd.name;%evt.dir;%proc.args;%evt.reltime" >capture3.txt


# We only consider the read and write file entries generated by wget and cp functions. And we also consider the execve systemcalls made. The 'traffic_gen.py' script generates the data which can be captured by the above sysdig command
# This file generates a file 'tuples.txt' which contains process name,operation and object in <proccess,op,obj> format for each entry in capture.txt
# To get the .dot file, write the output of the script to a .dot file eg:
# python3 parser.py > written.dot
import os
import re
from gvgen import GvGen
graph=GvGen()
graph.smart_mode=1
entities=set()
events=[]
objs={}
file= open('capture.txt','r')
lines=file.readlines()
dot_file=open('written.dot','w')
tuples_file=open('tuples.txt','w')
#file1=open('events.txt','w')
flag=0
evn=''
for ind1 in range(len(lines)-1):
	line=lines[ind1]
	components=line.split(';')
	flag=0
	if('>'==components[4]):
		item_to_find = ';'.join(components[0:4])+';<;'+components[5]
		#find event endTime
		indices=[ind2 for ind2 in range(ind1+1,len(lines)) if item_to_find in lines[ind2]]
		if indices!=[]:
			endTime=lines[indices[-1]].split(';')[-1].strip('\n')
		else:
			flag=1
		if(components[3]!='\n' and components[3]!='<NA>' and components[1]!='execve' and flag!=1):
			if(re.search("[0-9]*[.]+[0-9]*[.]+[0-9]*[.]+[0-9]*", components[3])):
				file=components[3].split('->')[-1].strip()
			else:
				file=components[3].strip()
			item="<"+components[0].strip()+","+components[1]+",'"+file+"'>"
			tuples_file.write(item)
			tuples_file.write('\n')
			evn=components[0].strip()+","+components[1]+","+file
			if(evn not in events):				
				events.append(evn)
				evn=''
				ts=components[-1].strip('\n')+';'+endTime
				#file1.write(line)
			if(components[0] not in entities):				
				entities.add(components[0])
				i1=graph.newItem(components[0])
				objs[components[0]]=i1
			else:
				i1=objs[components[0]]
			if(file not in entities):				
				entities.add(file)
				i2=graph.newItem(file)
				objs[components[3]]=i2              
			else:
				i2=objs[components[3]]
			if(components[1]=='read' or components[1]=='readv'):
				link=graph.newLink(i2,i1)
				graph.propertyAppend(link, "label", "read"+";"+ts)
			elif(components[1]=='write' or components[1]=='writev'):
				link=graph.newLink(i1,i2)
				graph.propertyAppend(link, "label", "write"+";"+ts)
		elif(components[1]=='execve' and flag!=1):
			args=components[5].strip()
			proc=components[0].strip()
			for a in args.split():
				if(a.isalpha()) or ('.py' in a):
					proc2=a
					break
			item="<"+components[0].strip()+","+components[1]+",'"+proc2+"'>"
			tuples_file.write(item)
			tuples_file.write('\n')
			if(evn not in events):
				events.append(evn)
				evn=''
				ts=components[-1].strip('\n')+';'+endTime
				#file1.write(line)
			if(proc not in entities):
				entities.add(proc)
				i1=graph.newItem(proc)
				objs[proc]=i1
			elif(proc in entities):
				i1=objs[proc]
			if(proc2 not in entities):
				entities.add(proc2)
				i2=graph.newItem(proc2)
				objs[proc2]=i2
			else:
				i2=objs[proc2]
				link=graph.newLink(i1,i2)
				graph.propertyAppend(link, "label", "call"+";"+ts)

graph.dot()
	# to_write.close()""" 
